async function paginar(url, tope){
  const out = [];
  let u = url;
  for (let i = 0; i < 10 && u && out.length < tope; i++){
    const r = await gGet(u);
    (r.data || []).forEach(x => out.push(x));
    u = (r.paging && r.paging.next) ? r.paging.next : null;
  }
  return out.slice(0, tope);
}

