const esDeNumero = e => /whats ?app|phone|n[uú]mero|1487246/i.test(String(e.message || '') + ' ' + String(e.titulo || '') + ' ' + (e.subcode || ''))
  && !/objetivo de rendimiento|performance goal|2490408/i.test(String(e.message || '') + ' ' + (e.subcode || ''));
