  const objetivoPlan = String(o.objetivo || '').toUpperCase();
  const ds = String(o.dataset || ((cfg && cfg.promoted_object) || {}).pixel_id || '');
  if (cfg && cfg.optimization_goal) {
    const po = Object.assign({}, cfg.promoted_object || {}, pg);
