  const utiles = lista_.filter(c => !(c.special_ad_categories || []).filter(x => x && x !== 'NONE').length
    && (!c.bid_strategy || c.bid_strategy === 'LOWEST_COST_WITHOUT_CAP'));
  const abo = c => !(Number(c.daily_budget) || Number(c.lifetime_budget));
