    lista_.filter(c => String(c.objective).toUpperCase() === obj && (!o.campanaRef || String(c.id) !== String(o.campanaRef.id))).slice(0, 2)
      .forEach(x => out.push({ id: String(x.id), cbo: !!(Number(x.daily_budget) || Number(x.lifetime_budget)) }));
