    if (r && r.body && typeof r.body !== 'object') { try { r.body = JSON.parse(String(r.body)); } catch (x) {} }
    else if (r && r.body && typeof Buffer !== 'undefined' && Buffer.isBuffer(r.body)) { try { r.body = JSON.parse(r.body.toString('utf8')); } catch (x) {} }
