  const clave = JSON.stringify([o.acc, o.pageId, o.meta, o.objetivoFijo || '', o.dataset || '', o.numero || '', (o.cfg || {}).optimization_goal || '', JSON.stringify((o.cfg || {}).promoted_object || {})]);
