    cache.__temporales = cache.__temporales || {};
    if (!cache.__temporales[l.temporal]) cache.__temporales[l.temporal] = await o.crearCampana(l.temporal);
    return cache.__temporales[l.temporal];
  };
  const numRef = ((o.cfg || {}).promoted_object || {}).whatsapp_phone_number || '';
  const numeros = (o.numero || numRef) ? variantesNumero(o.numero || numRef).slice(0, 4) : [''];
  const clave = JSON.stringify([o.acc, o.pageId, o.meta, o.objetivoFijo || '', o.dataset || '', o.numero || '', (o.cfg || {}).optimization_goal || '', JSON.stringify((o.cfg || {}).promoted_object || {})]);
  cache.__resueltos = cache.__resueltos || {};
  if (cache.__resueltos[clave]) return cache.__resueltos[clave];
  for (const cand of cands) {
    if (o.objetivoFijo && cand.objetivo !== String(o.objetivoFijo).toUpperCase()) continue;
    let lugares = [];
    try { lugares = await lugaresPara(cand.objetivo); } catch (e) {}
    if (!lugares.length) { sinPrueba.push(cand.objetivo); intentos.push({ etiqueta: cand.etiqueta, error: 'no hay en la cuenta una campaña de ' + (NOMBRE_OBJETIVO[cand.objetivo] || cand.objetivo) + ' donde probarla sin crear nada' }); continue; }
    let ultimo = null, aceptado = null, dondeOk = null, concluyente = false;
    for (const lugar of lugares) {
      let camp;
      try { camp = await materializar(lugar); } catch (e) { ultimo = e; continue; }
      ultimo = null;
    for (const n of numeros) {
      const po = Object.assign({}, cand.promoted_object); if (n) po.whatsapp_phone_number = n;
      const p = { name: 'mbe_validacion', campaign_id: camp.id, optimization_goal: cand.optimization_goal, billing_event: String(cand.billing_event || 'IMPRESSIONS').toUpperCase(),
        destination_type: 'WHATSAPP', promoted_object: po, status: 'PAUSED', execution_options: ['validate_only'],
        targeting: o.targeting || { geo_locations: { countries: ['MX'] }, age_min: 18, targeting_automation: { advantage_audience: 0 } } };
      if (!camp.cbo) p.daily_budget = aMenor(Math.max(Number(o.minimo) || 0, 50), o.moneda);
      if (cand.attribution_spec) p.attribution_spec = cand.attribution_spec.map(x => Object.assign({}, x, String(x.event_type).toUpperCase() === 'VIEW_THROUGH' && Number(x.window_days) > 1 ? { window_days: 1 } : {}));
      if (cand.optimization_sub_event && cand.optimization_sub_event !== 'NONE') p.optimization_sub_event = cand.optimization_sub_event;
      if (cand.bid_strategy && cand.bid_strategy !== 'LOWEST_COST_WITHOUT_CAP') p.bid_strategy = cand.bid_strategy;
      try { await gPost(o.acc + '/adsets', p); aceptado = po; dondeOk = camp.id; break; }
      catch (e) { ultimo = e; if (!n || !esDeNumero(e) || Number(e.subcode) === 2446886) break; }
    }
      if (aceptado) break;
      if (ultimo && !NO_CONCLUYENTE(ultimo)) { concluyente = true; break; }   /* rechazo real: no hace falta otra campaña */
    }
    if (!aceptado && ultimo && NO_CONCLUYENTE(ultimo) && !concluyente) { sinPrueba.push(cand.objetivo);
      intentos.push({ etiqueta: cand.etiqueta, error: 'no se pudo probar en las campañas de la cuenta (' + textoMeta(ultimo) + ')' }); continue; }
    if (aceptado) {
      const r = { ok: true, elegido: Object.assign({}, cand, { promoted_object: aceptado }), intentos, sinPrueba };
      return (cache.__resueltos[clave] = r);
    }
    intentos.push({ etiqueta: cand.etiqueta, error: !ultimo ? 'rechazada' : ([2446886, 1487246].indexOf(Number(ultimo.subcode)) >= 0 ? explicar(ultimo) : textoMeta(ultimo)) });
    /* Página sin WhatsApp vinculado: ninguna otra configuración puede funcionar. */
    if (ultimo && Number(ultimo.subcode) === 2446886) {
      const r = { ok: false, elegido: null, intentos, sinPrueba: [], paginaSinWA: true };
      return (cache.__resueltos[clave] = r);
    }
  }
  const r = { ok: false, elegido: null, intentos, sinPrueba };
  /* Compras sin conjunto de datos: la opción documentada por Meta no se pudo probar. */
  if (intencionWA(o.meta || (o.cfg && o.cfg.optimization_goal)) === 'COMPRAS' && !String(o.dataset || ((o.cfg || {}).promoted_object || {}).pixel_id || ''))
    r.faltaDataset = true;
  return (cache.__resueltos[clave] = r);
}
function textoIntentosWA(intentos){ return intentos.map((x, i) => (i + 1) + ') ' + x.etiqueta + ': ' + x.error).join(' · '); }
/* Compras por universo de medición (5.3), sin mezclar fuentes:
   - Campañas con "CAPI WhatsApp" en el nombre → compras en el chat (onsite_conversion.purchase,
     "On-Facebook Purchase").
   - Las demás → compras offline (offline_conversion.purchase, "Compras offline") y, si la cuenta
     no las registra, compras del sitio web (píxel).
   Nunca se suman ni se toma el mayor entre universos. */
function valorAccion(acts, tipo){ const x = (acts || []).find(a => a.action_type === tipo); return x ? Number(x.value) || 0 : 0; }
function comprasPorUniverso(acts, nombreCampana){
  if (/capi\s*whats\s*app/i.test(String(nombreCampana || ''))) return { compras: valorAccion(acts, 'onsite_conversion.purchase'), universo: 'chat' };
  const off = valorAccion(acts, 'offline_conversion.purchase');
  if (off) return { compras: off, universo: 'offline' };
  const web = valorAccion(acts, 'offsite_conversion.fb_pixel_purchase') || valorAccion(acts, 'purchase');
  return { compras: web, universo: web ? 'web' : '' };
}
function slug(s){
  return String(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'')
    .toLowerCase().replace(/[^a-z0-9]+/g,'_').replace(/^_+|_+$/g,'').slice(0,40) || 'cuenta';
}
function lista(v){
  if (Array.isArray(v)) return v.filter(Boolean).map(String);
  return String(v||'').split(',').map(s=>s.trim()).filter(Boolean);
}
/* Paginación completa: hasta 20 páginas de 100 (2.000 cuentas). */
async function todasLasCuentas(campos){
  let url = base + 'me/adaccounts?limit=100&fields=' + campos;
  const out = [];
  for (let i = 0; i < 20 && url; i++){
    const r = await gGet(url);
    (r.data || []).forEach(x => out.push(x));
    url = (r.paging && r.paging.next) ? r.paging.next : null;
  }
  return out;
}
/* Las llaves se asignan SIEMPRE en el mismo orden (account_id), así que no
   cambian entre llamadas ni entre nodos. */
function asignarLlaves(crudas){
  const activas = (crudas || [])
    .filter(a => Number(a.account_status) === 1)
    .sort((p,q) => String(p.account_id).localeCompare(String(q.account_id)));
  const vistos = {};
  activas.forEach(a => {
    let k = slug(a.name);
    if (vistos[k]) k = k + '_' + String(a.account_id).slice(-4);
    vistos[k] = true;
    a.__key = k;
  });
  return activas;
}
/* Identificador estable: account_id. El slug queda solo como respaldo. */
function resolverCuenta(crudas, cuentaId, clientKey){
  const activas = asignarLlaves(crudas);
  if (cuentaId) {
    const id = String(cuentaId).replace(/^act_/, '');
    const x = activas.filter(a => String(a.account_id) === id)[0];
    if (x) return x;
  }
  return activas.filter(a => a.__key === clientKey)[0] || null;
}
/* Offset de moneda en UN solo lugar. Verificar cada moneda nueva contra
   la referencia de Ad Account Currency antes de operar con ella. */
const OFFSET_1 = ['JPY','KRW','CLP','VND','COP','ISK','HUF','TWD','PYG','UGX',
                  'RWF','XAF','XOF','XPF','BIF','DJF','GNF','KMF','MGA','VUV'];
function offsetMoneda(m){ return OFFSET_1.indexOf(String(m||'').toUpperCase()) >= 0 ? 1 : 100; }
function aMenor(v, moneda){ const n = Number(v); if (!n) return null; return Math.round(n * offsetMoneda(moneda)); }
function aMayor(v, moneda){ return Number(v || 0) / offsetMoneda(moneda); }

/* Fecha en la zona horaria de la cuenta, no en la del contenedor (D1-05). */
function offsetDeZona(tz, fecha){
  try {
    const p = new Intl.DateTimeFormat('en-US', { timeZone: tz, timeZoneName: 'longOffset' })
      .formatToParts(fecha).filter(x => x.type === 'timeZoneName')[0].value;
    const off = String(p).replace('GMT', '');
    return off || '+00:00';
  } catch (e) { return '+00:00'; }
}
function isoEnZona(v, tz){
  if (!v) return null;
  const s = String(v).trim().replace(' ', 'T');
  if (/[zZ]$|[+-]\d{2}:\d{2}$/.test(s)) {
    const d0 = new Date(s);
    return isNaN(d0.getTime()) ? null : d0.toISOString();
  }
  const provisional = new Date(s + 'Z');
  if (isNaN(provisional.getTime())) return null;
  const d = new Date(s + offsetDeZona(tz || 'UTC', provisional));
  return isNaN(d.getTime()) ? null : d.toISOString();
}


/* ---- motor 5.5 · validación previa ----
   Corre DESPUÉS de responder al navegador (el proxy de Netlify corta a los 26 s):
   el rechazo llega por el sondeo de estado, no por esta respuesta. */
const b = $('Recibir').first().json.body || {};
const f = b.filas || {};
const problemas = [];

const camps  = f.campaigns || [];
const adsets = f.adsets || [];
const ads    = f.ads || [];
const assets = f.assets || [];
/* Campañas existentes: una por conjunto (campaign_id en la fila) o la global. */
const idsExistentes = [];
adsets.forEach(a => { if (a.campaign_id && idsExistentes.indexOf(String(a.campaign_id)) < 0) idsExistentes.push(String(a.campaign_id)); });
ads.forEach(a => { if (a.campaign_id && idsExistentes.indexOf(String(a.campaign_id)) < 0) idsExistentes.push(String(a.campaign_id)); });
/* Anuncios sobre conjuntos existentes: no hay conjuntos nuevos en el plan. */
const sobreConjuntos = ads.length > 0 && ads.every(a => a.adset_id);
if (b.campaign_id && idsExistentes.indexOf(String(b.campaign_id)) < 0) idsExistentes.push(String(b.campaign_id));
const usaExistente = idsExistentes.length > 0;

if (!camps.length && !usaExistente) problemas.push('El plan no trae ninguna campaña.');
if (!adsets.length && !ads.some(a => a.adset_id)) problemas.push('El plan no trae ningún conjunto.');
if (!ads.length)    problemas.push('El plan no trae ningún anuncio.');

/* Tope duro por corrida (D4-06). Ajustar según el tier de Marketing API. */
const TOPE_ADS = Number($vars.TOPE_ADS_POR_CORRIDA || 200);
if (ads.length > TOPE_ADS) {
  problemas.push('El plan trae ' + ads.length + ' anuncios y el tope por corrida es ' + TOPE_ADS
    + '. Divídelo en varias cargas.');
}

/* ---- la cuenta sigue asignada al system user (paginación completa) ---- */
let cuenta = null;
try {
  const crudas = await todasLasCuentas('account_id,name,currency,timezone_name,'
    + 'account_status,min_daily_budget');
  const a = resolverCuenta(crudas, b.cuenta_id, b.client_key);
  if (a) cuenta = {
    act: 'act_' + String(a.account_id).replace(/^act_/, ''),
    currency: a.currency,
    tz: a.timezone_name || 'UTC',
    minDiario: aMayor(a.min_daily_budget, a.currency),
  };
} catch (e) {
  problemas.push('No pude confirmar la cuenta en Meta: ' + explicar(e));
}
if (!cuenta && !problemas.length) {
  problemas.push('El system user ya no tiene acceso a la cuenta "'
    + (b.cuenta_id || b.client_key) + '".');
}

/* ---- destino WhatsApp (v3.4): permitido; se valida por conjunto más abajo ---- */
const esWhatsApp = a => String(a.destination_type || '').toUpperCase() === 'WHATSAPP';
const esFormulario = a => String(a.destination_type || '').toUpperCase() === 'ON_AD';

/* ---- campañas: nuevas y existentes conviven en el mismo plan (v3) ---- */
let campExistente = null;
let categoriasVigentes = [];        /* unión, para mensajes generales */
const catsPorCampana = {};          /* campaign_key → [categorías] */
const objetivoPorCampana = {};      /* campaign_key → objetivo real */
let estrategiaCampana = '';
const nombresExistentes = [];
const CON_IMPORTE = ['LOWEST_COST_WITH_BID_CAP','COST_CAP','TARGET_COST','LOWEST_COST_WITH_MIN_ROAS'];

camps.forEach(c => {
  catsPorCampana[c.campaign_key] = lista(c.special_ad_categories).map(x => String(x).toUpperCase()).filter(x => x && x !== 'NONE');
  catsPorCampana[c.campaign_key].forEach(x => { if (categoriasVigentes.indexOf(x) < 0) categoriasVigentes.push(x); });
});

if (usaExistente && cuenta) {
  for (const cid of idsExistentes) {
    const key = 'existente_' + cid;
    const mios = adsets.filter(a => String(a.campaign_id) === String(cid));
    try {
      const c = await gGet(base + cid + '?fields=id,name,objective,effective_status,'
        + 'daily_budget,lifetime_budget,account_id,special_ad_categories,bid_strategy');
      if (!campExistente) campExistente = c;
      nombresExistentes.push(c.name);
      catsPorCampana[key] = (c.special_ad_categories || []).filter(x => x && x !== 'NONE');
      objetivoPorCampana[key] = String(c.objective || '').toUpperCase();
      catsPorCampana[key].forEach(x => { if (categoriasVigentes.indexOf(x) < 0) categoriasVigentes.push(x); });
      if (String(c.account_id) !== cuenta.act.replace('act_','')) {
        problemas.push('La campaña "' + c.name + '" pertenece a otra cuenta publicitaria.');
      }
      if (['DELETED','ARCHIVED'].indexOf(c.effective_status) >= 0) {
        problemas.push('La campaña "' + c.name + '" está ' + c.effective_status + ' y no admite cambios.');
      }
      const cbo = !!(c.daily_budget || c.lifetime_budget);
      const conPresupuestoPropio = mios.some(a => Number(a.daily_budget) || Number(a.lifetime_budget));
      if (mios.length && cbo && conPresupuestoPropio) {
        problemas.push('La campaña "' + c.name + '" administra el presupuesto a nivel campaña: sus conjuntos nuevos no pueden traer monto.');
      }
      if (mios.length && !cbo && !mios.every(a => Number(a.daily_budget) || Number(a.lifetime_budget))) {
        problemas.push('La campaña "' + c.name + '" no tiene presupuesto propio: cada conjunto nuevo necesita el suyo.');
      }
      /* Estrategias con tope exigen bid_amount en cada conjunto (error 100/1815857). */
      const estr = String(c.bid_strategy || '').toUpperCase();
      if (mios.length && CON_IMPORTE.indexOf(estr) >= 0) {
        estrategiaCampana = estr;
        if (!mios.every(a => Number(a.bid_amount))) {
          problemas.push('La campaña "' + c.name + '" usa la estrategia de puja ' + estr
            + ', que obliga a fijar un importe por conjunto. Cambia la campaña a costo más bajo en Ads Manager '
            + 'o crea una campaña nueva desde aquí.');
        }
      }
    } catch (e) {
      problemas.push('No pude leer la campaña ' + cid + ': ' + explicar(e));
    }
  }
}

/* ---- campañas nuevas con puja con tope: cada conjunto nuevo necesita su importe (5.3) ---- */
camps.forEach(c => {
  const estr = String(c.bid_strategy || '').toUpperCase();
  if (CON_IMPORTE.indexOf(estr) < 0) return;
  adsets.filter(a => a.campaign_key === c.campaign_key && !a.clonar_conjunto_de && !Number(a.bid_amount))
    .forEach(a => problemas.push('El conjunto "' + a.name + '" está en una campaña con puja ' + estr + ' y no trae importe de puja. Captura el importe o usa costo más bajo.'));
});

/* ---- conjuntos existentes: siguen vivos y son de las campañas elegidas ---- */
if (ads.some(a => a.adset_id) && cuenta) {
  /* Una sola llamada por cada 50 conjuntos (?ids=) en vez de una por conjunto:
     el envío pasa por el proxy de Netlify, que corta las peticiones largas. */
  const idsConj = ads.filter(a => a.adset_id).map(a => String(a.adset_id));
  try {
    const leidos = await porIds(idsConj, 'id,name,campaign_id,effective_status');
    [...new Set(idsConj)].forEach(id => {
      const s = leidos[id];
      if (!s) { problemas.push('El conjunto ' + id + ' ya no existe o el token no tiene acceso.'); return; }
      if (['DELETED','ARCHIVED'].indexOf(s.effective_status) >= 0) problemas.push('El conjunto "' + s.name + '" está ' + s.effective_status + ' y no admite anuncios nuevos.');
      if (idsExistentes.length && idsExistentes.indexOf(String(s.campaign_id)) < 0) problemas.push('El conjunto "' + s.name + '" no pertenece a las campañas elegidas.');
    });
