      else if (String(x.account_id || '').replace('act_', '') && String(x.account_id).replace('act_', '') !== cuenta.act.replace('act_', '')
               && (adsets.some(a => a.clonar_conjunto_de === id) || camps.some(c => c.clonar_campana_de === id)))
